// Builds src/vendor/pdfjs-text.mjs: unpdf's serverless pdf.js, lowered to ES2020 by a current
// esbuild (2026-10-09). The Worker's text-layer read (lib/text-layer-read.js) needs pdf.js, and
// wrangler 3's esbuild miscompiles pdf.js's class static blocks ("Cannot set properties of
// undefined (setting '_isSameOrigin')" at start-up); code already lowered here gives it nothing
// to lower. Regenerate after an unpdf upgrade:
//   npx -y esbuild@0.24.0 --version && node src/vendor/build-pdfjs-text.mjs
import { execFileSync } from "node:child_process";
import { writeFileSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
const here = dirname(fileURLToPath(import.meta.url));
const entry = join(here, ".pdfjs-entry.mjs");
writeFileSync(entry, 'export { getDocument, Util, OPS } from "unpdf/pdfjs";\n');
const out = join(here, "pdfjs-text.mjs");
execFileSync("npx", ["-y", "esbuild@0.24.0", entry, "--bundle", "--format=esm", "--target=es2020", "--platform=neutral", "--main-fields=module,main", "--legal-comments=none", "--minify-syntax", "--outfile=" + out], { stdio: "inherit", cwd: join(here, "..", "..") });
const banner = "// GENERATED by src/vendor/build-pdfjs-text.mjs from unpdf " + JSON.parse(readFileSync(join(here, "..", "..", "node_modules/unpdf/package.json"), "utf8")).version + " (pdf.js, Apache-2.0). Do not edit.\n";
writeFileSync(out, banner + readFileSync(out, "utf8"));
